import os
import base64
from urllib.parse import quote

import requests
import streamlit as st

st.set_page_config(
    page_title="Market Intelligence Hub", page_icon="📊", layout="wide"
)

st.title("📊 NSE Futures & Strategy Market Intelligence Hub")
st.markdown(
    "Live dashboard displaying automated market reports generated by your GitHub"
    " Actions pipeline."
)

reports = {
    "⚡ Active Stocks": "active_stocks_report.txt",
    "📈 Strong Bullish & Bearish (RSI & SMA)": "confirmed_bullish_bearish_report.txt",
    "🎯 Active & Watchlist": [
        "relevant_active_stocks_report.txt",
        "rvol_active_signals_report.txt",
    ],
    "🎯 Consolidated Report": "consolidated_strategy_report.txt",
    "📈 Bullish Report": "bullish_report.txt",
    "📉 Bearish Report": "bearish_report.txt",
}

github_token = st.secrets.get("GITHUB_TOKEN", "").strip()


def trigger_github_workflow():
    if not github_token:
        st.sidebar.error("⚠️ GITHUB_TOKEN is not configured in Streamlit secrets.")
        return False

    owner = "SHANKARNBHAT"
    repo = "Report_Messenger_Claude"
    url = (
        f"https://api.github.com/repos/{owner}/{repo}/actions/workflows/"
        "pipeline.yml/dispatches"
    )
    headers = {
        "Authorization": f"Bearer {github_token}",
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
    }

    try:
        response = requests.post(
            url, json={"ref": "main"}, headers=headers, timeout=10
        )
    except requests.exceptions.RequestException as exc:
        st.sidebar.error(f"Failed to trigger workflow: {exc}")
        return False

    if response.status_code == 204:
        return True

    st.sidebar.error(f"Failed to trigger workflow: {response.text}")
    return False


def load_report_text(filename):
    owner = "SHANKARNBHAT"
    repo = "Report_Messenger_Claude"
    branch = "main"
    api_url = (
        f"https://api.github.com/repos/{owner}/{repo}/contents/{quote(filename)}"
    )

    if github_token:
        headers = {
            "Authorization": f"Bearer {github_token}",
            "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2022-11-28",
        }
        try:
            response = requests.get(
                api_url, headers=headers, params={"ref": branch}, timeout=5
            )
            response.raise_for_status()
            encoded_content = response.json().get("content")
            if not isinstance(encoded_content, str):
                raise ValueError(f"GitHub returned no file content for {filename}.")
            return base64.b64decode(encoded_content).decode("utf-8")
        except (
            requests.exceptions.RequestException,
            ValueError,
            UnicodeDecodeError,
        ) as exc:
            st.sidebar.warning(f"Could not load {filename} from GitHub: {exc}")
    else:
        st.sidebar.warning(
            "GITHUB_TOKEN is not configured; private reports use local snapshots."
        )

    if os.path.exists(filename):
        with open(filename, "r", encoding="utf-8") as report_file:
            return report_file.read()

    return (
        f"⚠️ Report file '{filename}' not found on GitHub. Click 'Run Workflow"
        " Now' in the sidebar to generate reports."
    )


st.sidebar.header("⚙️ Pipeline Controls")
st.sidebar.markdown(
    "If the daily batch hasn't run, you can manually trigger the workflow here:"
)

if st.sidebar.button("🚀 Run Workflow Now"):
    with st.spinner("Triggering GitHub Actions workflow..."):
        if trigger_github_workflow():
            st.sidebar.success(
                "Workflow triggered successfully! Refresh the page in a minute"
                " to see updated reports."
            )

st.sidebar.divider()

if st.sidebar.button("🔄 Refresh Reports"):
    st.rerun()

st.sidebar.markdown("Reports fetch real-time data directly from your repository.")
tabs = st.tabs(list(reports.keys()))

for tab, (report_name, file_target) in zip(tabs, reports.items()):
    with tab:
        st.subheader(report_name)

        if report_name == "🎯 Active & Watchlist":
            col1, col2 = st.columns(2)

            with col1:
                st.markdown("### 🎯 Relevant strategy following Active Stocks ")
                st.code(load_report_text(file_target[0]), language="text")

            with col2:
                st.markdown("### 👁️ Stocks to Watch from Strategy triggers")
                st.code(load_report_text(file_target[1]), language="text")
        else:
            st.code(load_report_text(file_target), language="text")
